            if inputs["item_weights"][i] > inputs["standard_weight_limits"][weight_limit_index]:
                tier_count = min(len(inputs["overweight_lower_bounds"]), len(inputs["overweight_upper_bounds"]), len(inputs["overweight_fees"]))
                for j in range(tier_count):
                    if inputs["item_weights"][i] > inputs["overweight_lower_bounds"][j] and inputs["item_weights"][i] <= inputs["overweight_upper_bounds"][j]:
                        overweight_fee = inputs["overweight_fees"][j]
                        break
